18	import {InMemorySessionStore} from './infrastructure/stores/inMemorySessionStore.js';
19	import {createApp} from './transport/createApp.js';
20	import type {HalAppOptions} from './transport/createApp.js';
21	import {createServer} from './transport/createServer.js';
22	import type {SessionResumeOptions} from './transport/ws/sessionResume.js';
23	
24	export interface HalEngineConfig {
25	  provider: ProviderConfig;
26	  resilience?: RetryPolicy;
27	  prompt: PromptBuilderConfig;
28	  tools?: ToolRegistry;
29	  session?: SessionStore;
30	  transport?: {
31	    port?: number;
32	    corsOrigin?: string | string[];
33	    basePath?: string;
34	    heartbeatIntervalMs?: number;
