42	    http?: HttpAuthMiddleware;
43	  };
44	  orchestrator?: {
45	    maxToolRounds?: number;
46	    /** How long one tool call may take before it is abandoned and answered with a timeout result; default 30000, and 0 waits forever. */
47	    toolTimeoutMs?: number;
48	    contextConfig?: Partial<ContextConfig>;
49	    /** Lifecycle hooks: called before and after each phase of processing a user message. */
50	    hooks?: OrchestratorHooks;
51	  };
52	  // Replaces the package's logger process-wide, not per engine: there is one `log` per process.
53	  logger?: Logger;
54	  onConnect?: (session: ChatSession, connection: ConnectInfo) => void | Promise<void>;
55	  onDisconnect?: (sessionId: string) => void | Promise<void>;
56	}
