64	export function createHalEngine(config: HalEngineConfig): HalEngine {
65	  // Before anything else builds, so a supplied logger receives this engine's first line.
66	  if (config.logger) setLogger(config.logger);
67	
68	  const toolRegistry = config.tools ?? new ToolRegistry();
69	  const sessionStore = config.session ?? new InMemorySessionStore();
70	  const basePath = config.transport?.basePath ?? '/hal';
71	
72	  const baseProvider = createProvider(config.provider);
73	  const provider = config.resilience ? withRetry(baseProvider, config.resilience) : baseProvider;
74	  const promptBuilder = new PromptBuilder(config.prompt);
75	  const orchestrator = createChatOrchestrator(provider, promptBuilder, toolRegistry, {
76	    maxToolRounds: config.orchestrator?.maxToolRounds,
77	    toolTimeoutMs: config.orchestrator?.toolTimeoutMs,
78	    contextConfig: config.orchestrator?.contextConfig,
79	    hooks: config.orchestrator?.hooks,
80	    sessionStore,
